  "implementation": "def solve(case):
    # Validate required fields
    if 'nodes' not in case or 'core_distance' not in case or 'distances' not in case:
        raise ValueError('Missing required fields: nodes, core_distance, distances')
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Quick validation
    if not isinstance(nodes, list) or not isinstance(core_dist, dict) or not isinstance(distances, list):
        raise ValueError('Invalid field types')

    n = len(nodes)
    if n == 0:
        return {'mst_edges': [], 'total_weight': 0.0}

    # Build edges: (weight, u, v) with u<v lexicographically
    edges = []
    for d in distances:
        if len(d) != 3:
            raise ValueError('Each distance entry must have 3 elements')
        u, v, w = d
        if u not in core_dist or v not in core_dist:
            raise ValueError('Node in distance not in core_distance')
        mutual = max(core_dist[u], core_dist[v], w)
        # canonicalize endpoint order
        if u < v:
            edges.append((mutual, u, v))
        else:
            edges.append((mutual, v, u))

    # Sort by weight, then first node, then second node (deterministic tie-breaking)
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected; cannot compute MST')

    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
}
